INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('INS-15', 'INSURANCE', '논작물 수확감소보장', '제3절 논작물(벼·조사료용 벼·밀·보리·귀리 5종) 수확감소보장. 자연재해 등 보장재해 피해로 수확량이 감소한 것에 대한 보상. 시기별 조사: 예찰 / 피해사실확인 / 이앙·직파불능(벼) / 재이앙·재직파(벼) / 경작불능 / 수확불능(벼) / 수확량(수량요소·표본·전수). 수확량조사 우선순위 = 전수 > 표본 > 수량요소.', '논작물 수확감소보장', NULL, NULL, 'p.501', 501, 508, '제2편 농작물재해보험 손해평가', '제3절 논작물(벼, 맥류) 손해평가 및 보험금 산정', 'BATCH-3', 2026, 8, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('INS-16', 'INSURANCE', '이앙·직파불능 보장 (벼)', '벼 전용. 이앙 한계일(7월 31일) 까지 보상재해로 인한 농지 전체 이앙·직파 불능 시 적용. 통상적인 영농활동(논둑 정리, 논갈이, 비료시비, 제초제 살포 등) 이행 의무.', '논작물 수확감소보장', NULL, NULL, 'p.503', 503, 510, '제2편 농작물재해보험 손해평가', '제3절 논작물(벼, 맥류) 손해평가 및 보험금 산정', 'BATCH-3', 2026, 8, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('INS-17', 'INSURANCE', '재이앙·재직파 보장 (벼)', '벼 전용. 면적피해율 10% 초과 시 적용. 피해면적 = 묘 분리 + 묘 묻힘/잎차단 + 수확 불가 면적. 재이앙·재직파 후 조사로 이행 완료 여부 확인 — 일부만 재이앙된 경우 미이행 면적 제외.', '논작물 수확감소보장', NULL, NULL, 'p.504', 504, 511, '제2편 농작물재해보험 손해평가', '제3절 논작물(벼, 맥류) 손해평가 및 보험금 산정', 'BATCH-3', 2026, 8, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('INS-18', 'INSURANCE', '논작물 경작불능 보장', '5종 작물 모두 적용. 식물체피해율 65% 이상(분질미 60% 이상) AND 계약자 신청 시 적용. 산지폐기 여부 확인 후 지급. 미만 또는 미신청 시 수확량조사 진행 (조사료용 벼 제외).', '논작물 수확감소보장', NULL, NULL, 'p.506', 506, 513, '제2편 농작물재해보험 손해평가', '제3절 논작물(벼, 맥류) 손해평가 및 보험금 산정', 'BATCH-3', 2026, 8, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('INS-19', 'INSURANCE', '수확불능 보장 (벼)', '벼 전용. 제현율 65%(분질미 70%) 미만으로 정상 출하 불가능 시 적용. 단 경작불능보험금 대상인 경우 수확불능에서 제외 (이중 보장 X).', '논작물 수확감소보장', NULL, NULL, 'p.509', 509, 516, '제2편 농작물재해보험 손해평가', '제3절 논작물(벼, 맥류) 손해평가 및 보험금 산정', 'BATCH-3', 2026, 8, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('INS-20', 'INSURANCE', '무화과 나무손해보장 특별약관', '무화과 전용. 나무손해보장 일반(INS-11)과 별도 — 자기부담비율 5% 고정. 보험금 = 보험가입금액 × (피해율 - 0.05). 피해율 = 피해주수 ÷ 실제결과주수.', '나무손해보장', NULL, NULL, 'p.500', 500, 507, '제2편 농작물재해보험 손해평가', '4. 수확전 종합위험 과실손해보장방식', 'BATCH-3', 2026, 8, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('CROP-023', 'CROP', '벼', '논작물 5종 중 1. 이앙·직파불능 / 재이앙·재직파 / 수확불능 보장 적용 (벼만 해당). 병해충 단독사고 보장. 수량요소조사·표본조사·전수조사 모두 적용. 수량요소 4 표본포기 (가입면적 무관).', '논작물 수확감소보장', NULL, NULL, 'p.501', 501, 508, '제2편 농작물재해보험 손해평가', '제3절 논작물(벼, 맥류) 손해평가 및 보험금 산정', 'BATCH-3', 2026, 6, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('CROP-024', 'CROP', '조사료용 벼', '논작물 5종 중 1. 수확량조사 제외 (수확이 풀 사료 단위라 단위면적당 무게 산정 불가). 경작불능 보장만 적용 가능 — 식물체피해율 65% 이상 시 분기.', '논작물 수확감소보장', NULL, NULL, 'p.501', 501, 508, '제2편 농작물재해보험 손해평가', '제3절 논작물(벼, 맥류) 손해평가 및 보험금 산정', 'BATCH-3', 2026, 6, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('CROP-025', 'CROP', '밀', '맥류 3종 중 1. 표본조사 + 전수조사 적용 (수량요소조사 X — 벼 전용). 점파/산파 표본구간 — 점파 4포기 길이+간격, 산파/이랑 불명확 시 50×50cm 규격 테 사용.', '논작물 수확감소보장', NULL, NULL, 'p.513', 513, 520, '제2편 농작물재해보험 손해평가', '제3절 논작물(벼, 맥류) 손해평가 및 보험금 산정', 'BATCH-3', 2026, 6, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('CROP-026', 'CROP', '보리', '맥류 3종 중 1. 밀과 동일 표본 단위. 함수율 측정 3회 평균 의무.', '논작물 수확감소보장', NULL, NULL, 'p.513', 513, 520, '제2편 농작물재해보험 손해평가', '제3절 논작물(벼, 맥류) 손해평가 및 보험금 산정', 'BATCH-3', 2026, 6, 'draft');
