INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('INV-041', 'INVESTIGATION', '논작물 예찰조사', '사고 미접수 상태에서 보험 목적의 위험상태 조사. 모든 논작물 5종 적용. 추가조사 필요 여부 판단의 사전 단계.', '논작물 수확감소보장', NULL, NULL, 'p.502', 502, 509, '제2편 농작물재해보험 손해평가', '제3절 논작물(벼, 맥류) 손해평가 및 보험금 산정', 'BATCH-3', 2026, 7, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('INV-042', 'INVESTIGATION', '논작물 피해사실 확인조사', '사고 접수 직후 실시. 보장재해 여부 + 피해정도 감안 추가조사 필요 여부 판단 (이앙·직파불능 / 재이앙·재직파 / 경작불능 / 수확량 중). 태풍 등 명확 시 또는 직후 추가조사 필요 시 생략 가능.', '논작물 수확감소보장', NULL, NULL, 'p.503', 503, 510, '제2편 농작물재해보험 손해평가', '제3절 논작물(벼, 맥류) 손해평가 및 보험금 산정', 'BATCH-3', 2026, 7, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('INV-043', 'INVESTIGATION', '이앙·직파불능 조사', '벼 전용. 이앙 한계일(7월 31일) 이후 실시. 보장재해 심사 + 실제 경작면적 확인 + 이앙·직파불능 판정 + 통상적 영농활동(논둑정리·논갈이·비료시비·제초제) 이행 여부 4단계.', '논작물 수확감소보장', NULL, NULL, 'p.503', 503, 510, '제2편 농작물재해보험 손해평가', '제3절 논작물(벼, 맥류) 손해평가 및 보험금 산정', 'BATCH-3', 2026, 7, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('INV-044', 'INVESTIGATION', '재이앙·재직파 조사', '벼 전용. 사고 접수 직후 실시. 1차 = 재이앙·재직파 전(前) 조사: 보장재해 + 실제경작면적 + 피해면적 확인. 2차 = 재이앙·재직파 후(後) 조사: 이행 완료 여부 — 일부만 재이앙된 경우 미이행 면적 제외. 면적피해율 10% 초과 트리거.', '논작물 수확감소보장', NULL, NULL, 'p.504', 504, 511, '제2편 농작물재해보험 손해평가', '제3절 논작물(벼, 맥류) 손해평가 및 보험금 산정', 'BATCH-3', 2026, 7, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('INV-045', 'INVESTIGATION', '논작물 경작불능 조사', '5종 작물 모두 적용. 사고 접수 후 지체없이. 식물체피해율 65%(분질미 60%) 목측 조사 → 계약자 신청 여부 → 산지폐기 확인. 수확량조사 대상 확인 분기 (조사료용 벼 제외 / 벼 미신청 시).', '논작물 수확감소보장', NULL, NULL, 'p.506', 506, 513, '제2편 농작물재해보험 손해평가', '제3절 논작물(벼, 맥류) 손해평가 및 보험금 산정', 'BATCH-3', 2026, 7, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('INV-046', 'INVESTIGATION', '수확불능 확인조사 (벼)', '벼 전용. 수확포기가 확인되는 시점 실시. 제현율 65%(분질미 70%) 미만 → 정상 출하 불가능 판정 → 수확불능 보험금. 경작불능보험금 대상 시 제외.', '논작물 수확감소보장', NULL, NULL, 'p.509', 509, 516, '제2편 농작물재해보험 손해평가', '제3절 논작물(벼, 맥류) 손해평가 및 보험금 산정', 'BATCH-3', 2026, 7, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('INV-047', 'INVESTIGATION', '수량요소조사 (벼만)', '벼 전용. 수확 전 14일 전후 실시. 4 표본포기 선정 (가입면적 무관) → 이삭상태 점수(LAW-011) + 완전낟알상태 점수(LAW-012) 합산 → 조사수확비율 환산표(LAW-013) lookup → 피해면적 보정계수(LAW-014) 적용. 병해충 단독사고 여부 확인.', '논작물 수확감소보장', NULL, NULL, 'p.509', 509, 516, '제2편 농작물재해보험 손해평가', '제3절 논작물(벼, 맥류) 손해평가 및 보험금 산정', 'BATCH-3', 2026, 7, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('INV-048', 'INVESTIGATION', '표본조사 (논작물)', '5종 작물 적용 (조사료용 벼 제외). 알곡 여물어 수확 가능 시기. 별표1 표본주(구간)수표 → 표본구간 선정 → 표본구간 면적(벼 4포기 길이+간격, 밀/보리/귀리 점파 동일 또는 산파 시 50×50cm 테) + 표본 중량 + 함수율 3회 평균.', '논작물 수확감소보장', NULL, NULL, 'p.512', 512, 519, '제2편 농작물재해보험 손해평가', '제3절 논작물(벼, 맥류) 손해평가 및 보험금 산정', 'BATCH-3', 2026, 7, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('INV-049', 'INVESTIGATION', '전수조사 (논작물)', '기계수확(탈곡 포함) 농지 한정. 수확 시 실시. 조곡의 중량 조사. 5종 모두 적용 가능. 우선순위 1순위 (전수 > 표본 > 수량요소).', '논작물 수확감소보장', NULL, NULL, 'p.514', 514, 521, '제2편 농작물재해보험 손해평가', '제3절 논작물(벼, 맥류) 손해평가 및 보험금 산정', 'BATCH-3', 2026, 7, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('INV-050', 'INVESTIGATION', '함수율 조사', '수확한 작물에 대한 함수율 측정 3회 이상 평균값 산출. 표본조사·전수조사 공통 단계.', '논작물 수확감소보장', NULL, NULL, 'p.513', 513, 520, '제2편 농작물재해보험 손해평가', '제3절 논작물(벼, 맥류) 손해평가 및 보험금 산정', 'BATCH-3', 2026, 6, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('INV-051', 'INVESTIGATION', '병해충 단독사고 확인 (벼만)', '벼 전용. 자연재해/조수해/화재 무관 보상하는 병해충만으로 발생한 경우. 가장 주된 병해충명 조사 의무. 수량요소·표본조사 모두 적용.', '논작물 수확감소보장', NULL, NULL, 'p.512', 512, 519, '제2편 농작물재해보험 손해평가', '제3절 논작물(벼, 맥류) 손해평가 및 보험금 산정', 'BATCH-3', 2026, 7, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('INV-052', 'INVESTIGATION', '논작물 면적 5단계 확인', '실제경작면적 → 고사면적 → 타작물·미보상면적 → 기수확면적 → 조사대상면적 (= 실제경작 - 고사 - 타작물미보상 - 기수확). GPS 면적측정기·지형도 사용. 가입면적 대비 10% 이상 차이 시 계약 변경.', '논작물 수확감소보장', NULL, NULL, 'p.509', 509, 516, '제2편 농작물재해보험 손해평가', '제3절 논작물(벼, 맥류) 손해평가 및 보험금 산정', 'BATCH-3', 2026, 7, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('INV-053', 'INVESTIGATION', '무화과 (특정위험) 과실손해조사', '무화과 8월 1일 이후 사고 영역. 보험기간 = 가입 이듬해 8월 1일 이후 ~ 수확기 종료 시점. 조사대상주수 → 표본주 → 결과지피해율 산정.', '수확전 종합위험 과실손해보장', NULL, NULL, 'p.495', 495, 502, '제2편 농작물재해보험 손해평가', '4. 수확전 종합위험 과실손해보장방식', 'BATCH-3', 2026, 7, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('INV-054', 'INVESTIGATION', '복분자 (특정위험) 과실손해조사', '복분자 6월 1일 이후 사고 영역. 보험기간 = 가입 이듬해 6월 1일 ~ 6월 20일. 살아있는 결과모지수 + 수정불량환산 고사결과모지수 + 수확감소환산 고사결과모지수 산정.', '수확전 종합위험 과실손해보장', NULL, NULL, 'p.494', 494, 501, '제2편 농작물재해보험 손해평가', '4. 수확전 종합위험 과실손해보장방식', 'BATCH-3', 2026, 7, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('CONCEPT-052', 'CONCEPT', '식물체 피해율 (논작물)', '논작물 경작불능 분기 임계치. 65% 이상(분질미 60% 이상) AND 계약자 신청 시 경작불능보험금. 미만 또는 미신청 시 수확량조사 분기 (조사료용 벼 제외).', '논작물 수확감소보장', NULL, NULL, 'p.507', 507, 514, '제2편 농작물재해보험 손해평가', '제3절 논작물(벼, 맥류) 손해평가 및 보험금 산정', 'BATCH-3', 2026, 7, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('CONCEPT-053', 'CONCEPT', '면적피해율', '피해면적 ÷ 실제경작면적. 재이앙·재직파 트리거 = 10% 초과. 피해면적 판정 = 묘 분리 + 묘 묻힘/잎차단 + 수확 불가.', '논작물 수확감소보장', NULL, NULL, 'p.505', 505, 512, '제2편 농작물재해보험 손해평가', '제3절 논작물(벼, 맥류) 손해평가 및 보험금 산정', 'BATCH-3', 2026, 7, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('CONCEPT-054', 'CONCEPT', '제현율', '벼 껍질을 벗겨낸 비율. 65% 미만(분질미 70% 미만) 시 수확불능 트리거. 정상 출하 가능 여부 판정.', '논작물 수확감소보장', NULL, NULL, 'p.509', 509, 516, '제2편 농작물재해보험 손해평가', '제3절 논작물(벼, 맥류) 손해평가 및 보험금 산정', 'BATCH-3', 2026, 7, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('CONCEPT-055', 'CONCEPT', '분질미 임계 보정', '분질미(쌀가루용 벼 변종) — 식물체피해율 60%(일반 65%), 제현율 70%(일반 65%). 일반 벼와 다른 임계치 적용.', '논작물 수확감소보장', NULL, NULL, 'p.507', 507, 514, '제2편 농작물재해보험 손해평가', '제3절 논작물(벼, 맥류) 손해평가 및 보험금 산정', 'BATCH-3', 2026, 7, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('CONCEPT-056', 'CONCEPT', '결실률', '전체결실수 ÷ 전체개화수. 복분자 수확감소환산계수 산식 인자.', '수확전 종합위험 과실손해보장', NULL, NULL, 'p.499', 499, 506, '제2편 농작물재해보험 손해평가', '4. 수확전 종합위험 과실손해보장방식', 'BATCH-3', 2026, 7, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('CONCEPT-057', 'CONCEPT', '자연수정불량률 (복분자)', '15% 고정 (2014 복분자 수확량 연구용역 결과). 수정불량환산계수 산정 시 차감 인자 — 자연 발생 분 제외.', '수확전 종합위험 과실손해보장', NULL, NULL, 'p.498', 498, 505, '제2편 농작물재해보험 손해평가', '4. 수확전 종합위험 과실손해보장방식', 'BATCH-3', 2026, 7, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('CONCEPT-058', 'CONCEPT', '결과모지수', '복분자 결과지보다 1년 더 묵은 가지 단위. 평년/살아있는/고사/수확감소환산/수정불량환산/미보상 6 변종.', '수확전 종합위험 과실손해보장', NULL, NULL, 'p.498', 498, 505, '제2편 농작물재해보험 손해평가', '4. 수확전 종합위험 과실손해보장방식', 'BATCH-3', 2026, 7, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('CONCEPT-059', 'CONCEPT', '수확감소환산 고사결과모지수', '5/31 이전 사고 있음 = (살아있는 - 수정불량환산고사) × 누적수확감소환산계수 / 5/31 이전 없음 = 평년결과모지수 × 누적수확감소환산계수. 두 케이스 분기.', '수확전 종합위험 과실손해보장', NULL, NULL, 'p.499', 499, 506, '제2편 농작물재해보험 손해평가', '4. 수확전 종합위험 과실손해보장방식', 'BATCH-3', 2026, 7, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('CONCEPT-060', 'CONCEPT', '누적수확감소환산계수', '수확감소환산계수의 누적 값. 수확감소환산계수 = 수확일자별 잔여수확량 비율 - 결실률.', '수확전 종합위험 과실손해보장', NULL, NULL, 'p.499', 499, 506, '제2편 농작물재해보험 손해평가', '4. 수확전 종합위험 과실손해보장방식', 'BATCH-3', 2026, 7, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('CONCEPT-061', 'CONCEPT', '수확일자별 잔여수확량 비율 (복분자)', '6월 1일~7일 = 98 - 사고발생일자. 6월 8일~20일 = 사고발생일자 × 사고발생일자. 사고일자별 비율 함수.', '수확전 종합위험 과실손해보장', NULL, NULL, 'p.499', 499, 506, '제2편 농작물재해보험 손해평가', '4. 수확전 종합위험 과실손해보장방식', 'BATCH-3', 2026, 7, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('CONCEPT-062', 'CONCEPT', '무화과 경과비율', '8월 = 100 - 1.06 × 사고발생일자. 9월 = (100-33) - 1.13 × 사고발생일자. 10월 = (100-67) - 0.84 × 사고발생일자. 단위 %. 8/1 이후 사고피해율 산식 인자.', '수확전 종합위험 과실손해보장', NULL, NULL, 'p.500', 500, 507, '제2편 농작물재해보험 손해평가', '4. 수확전 종합위험 과실손해보장방식', 'BATCH-3', 2026, 7, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('CONCEPT-063', 'CONCEPT', '결과지피해율 (무화과)', '(고사결과지수 + 미고사결과지수×착과피해율 - 미보상고사결과지수) ÷ 기준결과지수. 기준결과지수 = 고사+미고사. 8/1 이후 사고피해율 인자.', '수확전 종합위험 과실손해보장', NULL, NULL, 'p.500', 500, 507, '제2편 농작물재해보험 손해평가', '4. 수확전 종합위험 과실손해보장방식', 'BATCH-3', 2026, 7, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('CONCEPT-064', 'CONCEPT', '수량요소조사 점수 합계', '이삭상태 점수(4 표본포기 합 4~8) + 완전낟알상태 점수(4 표본포기 합 4~20) = 8~28점. LAW-013 환산표 lookup 으로 조사수확비율(%) 산정.', '논작물 수확감소보장', NULL, NULL, 'p.511', 511, 518, '제2편 농작물재해보험 손해평가', '제3절 논작물(벼, 맥류) 손해평가 및 보험금 산정', 'BATCH-3', 2026, 7, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('CONCEPT-065', 'CONCEPT', '조사수확비율', '수량요소조사 점수 합계의 % 환산값 (LAW-013). 0~20% (10미만) ~ 91~100% (24이상) 8 구간. 표본포기 4개 점수 합계 → 환산.', '논작물 수확감소보장', NULL, NULL, 'p.512', 512, 519, '제2편 농작물재해보험 손해평가', '제3절 논작물(벼, 맥류) 손해평가 및 보험금 산정', 'BATCH-3', 2026, 7, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('CONCEPT-066', 'CONCEPT', '피해면적 보정계수', '매우경미(<10%)=1.2 / 경미(10~30%)=1.1 / 보통(≥30%)=1.0. 수량요소조사 산식 보정 인자.', '논작물 수확감소보장', NULL, NULL, 'p.512', 512, 519, '제2편 농작물재해보험 손해평가', '제3절 논작물(벼, 맥류) 손해평가 및 보험금 산정', 'BATCH-3', 2026, 7, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('CONCEPT-067', 'CONCEPT', '함수율', '수확한 작물의 수분 함량 비율. 3회 이상 측정 평균. 표본조사·전수조사 공통.', '논작물 수확감소보장', NULL, NULL, 'p.513', 513, 520, '제2편 농작물재해보험 손해평가', '제3절 논작물(벼, 맥류) 손해평가 및 보험금 산정', 'BATCH-3', 2026, 6, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('CONCEPT-068', 'CONCEPT', '단위면적당 조사수확량', '표본조사·전수조사의 핵심 출력값. 조사 대상 면적에 적용되어 총 수확량 산정. 인접 농지(동일 ''리'') 적용 가능.', '논작물 수확감소보장', NULL, NULL, 'p.508', 508, 515, '제2편 농작물재해보험 손해평가', '제3절 논작물(벼, 맥류) 손해평가 및 보험금 산정', 'BATCH-3', 2026, 7, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('CONCEPT-069', 'CONCEPT', '통상적 영농활동 (벼)', '이앙·직파불능 보장 트리거 의무. 논둑 정리 + 논갈이 + 비료시비 + 제초제 살포. 미이행 시 보장 거부 가능.', '논작물 수확감소보장', NULL, NULL, 'p.504', 504, 511, '제2편 농작물재해보험 손해평가', '제3절 논작물(벼, 맥류) 손해평가 및 보험금 산정', 'BATCH-3', 2026, 7, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('TERM-025', 'TERM', '결과모지', '복분자 결과지보다 1년 더 묵은 가지. 결과모지수 산정 단위. p.490(BATCH-2) 정의 참조.', '수확전 종합위험 과실손해보장', NULL, NULL, 'p.498', 498, 505, '제2편 농작물재해보험 손해평가', '4. 수확전 종합위험 과실손해보장방식', 'BATCH-3', 2026, 5, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('TERM-026', 'TERM', '결과지', '무화과 결실 가능한 가지. 결과지피해율 산정 단위. 고사·미고사·미보상 분류.', '수확전 종합위험 과실손해보장', NULL, NULL, 'p.500', 500, 507, '제2편 농작물재해보험 손해평가', '4. 수확전 종합위험 과실손해보장방식', 'BATCH-3', 2026, 5, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('TERM-027', 'TERM', '분질미', '쌀가루(米粉) 가공용 벼 변종. 일반 벼와 다른 임계치 — 식물체피해율 60%(일반 65%), 제현율 70%(일반 65%) — 임계 보정 적용.', '논작물 수확감소보장', NULL, NULL, 'p.507', 507, 514, '제2편 농작물재해보험 손해평가', '제3절 논작물(벼, 맥류) 손해평가 및 보험금 산정', 'BATCH-3', 2026, 6, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('TERM-028', 'TERM', '조곡', '벼 껍질 + 알곡. 전수조사에서 조곡의 중량 조사 단위. 제현 = 벼의 껍질을 벗겨내는 것.', '논작물 수확감소보장', NULL, NULL, 'p.509', 509, 516, '제2편 농작물재해보험 손해평가', '제3절 논작물(벼, 맥류) 손해평가 및 보험금 산정', 'BATCH-3', 2026, 5, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('TERM-029', 'TERM', '표본 포기', '논작물 수량요소조사 단위. 4 포기(가입면적 무관). 부적합 시 가까운 위치의 다른 포기로 대체.', '논작물 수확감소보장', NULL, NULL, 'p.509', 509, 516, '제2편 농작물재해보험 손해평가', '제3절 논작물(벼, 맥류) 손해평가 및 보험금 산정', 'BATCH-3', 2026, 5, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('TERM-030', 'TERM', '표본구간', '논작물 표본조사 단위. 별표1 표본주(구간)수표 기준 산정. 조사대상 면적에 동일 간격 골고루 배치.', '논작물 수확감소보장', NULL, NULL, 'p.512', 512, 519, '제2편 농작물재해보험 손해평가', '제3절 논작물(벼, 맥류) 손해평가 및 보험금 산정', 'BATCH-3', 2026, 5, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('TERM-031', 'TERM', '이앙 한계일', '7월 31일. 이앙·직파불능 보장 판정 기준일 — 본 일자까지 농지 전체 이앙·직파 미완료 시 이앙·직파불능 피해 판정.', '논작물 수확감소보장', NULL, NULL, 'p.501', 501, 508, '제2편 농작물재해보험 손해평가', '제3절 논작물(벼, 맥류) 손해평가 및 보험금 산정', 'BATCH-3', 2026, 7, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('TERM-032', 'TERM', '점파 / 산파', '맥류 파종 방식. 점파 = 일정 간격 파종 (4 포기 길이+간격 표본). 산파 = 흩어 뿌리기 (이랑 불명확) — 50×50cm 규격 테 사용.', '논작물 수확감소보장', NULL, NULL, 'p.513', 513, 520, '제2편 농작물재해보험 손해평가', '제3절 논작물(벼, 맥류) 손해평가 및 보험금 산정', 'BATCH-3', 2026, 5, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('LAW-010', 'LAW', '별표 자기부담비율별 경작불능보험금 지급비율표 (복분자)', '10%형 = 45% / 15%형 = 42% / 20%형 = 40% / 30%형 = 35% / 40%형 = 30%. 복분자 경작불능보험금 산식 핵심 lookup.', '수확전 종합위험 과실손해보장', NULL, NULL, 'p.498', 498, 505, '별표', '별표 자기부담비율별 경작불능보험금 지급비율표', 'BATCH-3', 2026, 8, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('LAW-011', 'LAW', '별표 이삭상태 점수표 (벼)', '포기당 이삭수 < 16 = 1점 / ≥ 16 = 2점. 수량요소조사 점수 합계 산정 인자.', '논작물 수확감소보장', NULL, NULL, 'p.510', 510, 517, '별표', '별표 이삭상태 점수표', 'BATCH-3', 2026, 8, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('LAW-012', 'LAW', '별표 완전낟알상태 점수표 (벼)', '이삭당 완전낟알수 5 단계: 51미만=1점, 51~61미만=2점, 61~71미만=3점, 71~81미만=4점, 81이상=5점. 수량요소조사 점수 합계 산정 인자.', '논작물 수확감소보장', NULL, NULL, 'p.511', 511, 518, '별표', '별표 완전낟알상태 점수표', 'BATCH-3', 2026, 8, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('LAW-013', 'LAW', '별표 조사수확비율 환산표 (벼)', '점수 합계 → 조사수확비율 8단계: <10=0~20%, 10~11=21~40%, 12~13=41~50%, 14~15=51~60%, 16~18=61~70%, 19~21=71~80%, 22~23=81~90%, ≥24=91~100%.', '논작물 수확감소보장', NULL, NULL, 'p.512', 512, 519, '별표', '별표 조사수확비율 환산표', 'BATCH-3', 2026, 8, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('LAW-014', 'LAW', '별표 피해면적 보정계수', '피해정도 3단계: 매우경미(<10%)=1.2 / 경미(10~30%)=1.1 / 보통(≥30%)=1.0. 수량요소조사 결과 보정 인자.', '논작물 수확감소보장', NULL, NULL, 'p.512', 512, 519, '별표', '별표 피해면적 보정계수', 'BATCH-3', 2026, 8, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('LAW-015', 'LAW', '별표 수확일자별 잔여수확량 비율 (복분자/무화과)', '복분자: 6월 1~7일=98-사고발생일자, 6월 8~20일=사고발생일자×사고발생일자. 무화과: 8월=100-1.06×사고발생일자, 9월=(100-33)-1.13×사고발생일자, 10월=(100-67)-0.84×사고발생일자.', '수확전 종합위험 과실손해보장', NULL, NULL, 'p.499', 499, 506, '별표', '별표 수확일자별 잔여수확량 비율', 'BATCH-3', 2026, 8, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('F-34', 'FORMULA', '복분자 경작불능보험금', 'F-34 복분자 경작불능보험금 산식 노드. equation_template: insurance_amount × deductible_payout_rate. 자기부담비율별 지급비율 lookup (LAW-010).', '수확전 종합위험 과실손해보장', NULL, NULL, 'p.498', 498, 505, '제2편 농작물재해보험 손해평가', '4. 수확전 종합위험 과실손해보장방식', 'BATCH-3', 2026, 9, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('F-35', 'FORMULA', '복분자 과실손해보험금', 'F-35 복분자 과실손해보험금 산식 노드. equation_template: max(insurance_amount × (damage_rate - deductible_rate), 0).', '수확전 종합위험 과실손해보장', NULL, NULL, 'p.498', 498, 505, '제2편 농작물재해보험 손해평가', '4. 수확전 종합위험 과실손해보장방식', 'BATCH-3', 2026, 9, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('F-36', 'FORMULA', '복분자 피해율', 'F-36 복분자 피해율 산식 노드. equation_template: dead_branches / expected_branches. 고사결과모지수 ÷ 평년결과모지수.', '수확전 종합위험 과실손해보장', NULL, NULL, 'p.498', 498, 505, '제2편 농작물재해보험 손해평가', '4. 수확전 종합위험 과실손해보장방식', 'BATCH-3', 2026, 9, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('F-37', 'FORMULA', '복분자 5/31 이전 고사결과모지수', 'F-37 복분자 5/31 이전 고사결과모지수 산식 노드. equation_template: (expected - alive) + invalid_pollination - uncovered.', '수확전 종합위험 과실손해보장', NULL, NULL, 'p.498', 498, 505, '제2편 농작물재해보험 손해평가', '4. 수확전 종합위험 과실손해보장방식', 'BATCH-3', 2026, 9, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('F-38', 'FORMULA', '복분자 6/1 이후 고사결과모지수', 'F-38 복분자 6/1 이후 고사결과모지수 산식 노드. equation_template: yield_loss - uncovered.', '수확전 종합위험 과실손해보장', NULL, NULL, 'p.498', 498, 505, '제2편 농작물재해보험 손해평가', '4. 수확전 종합위험 과실손해보장방식', 'BATCH-3', 2026, 9, 'draft');
