INSERT OR IGNORE INTO formulas (id, name, equation_template, variables_schema, page_ref, node_id, version_year) VALUES ('F-34', '복분자 경작불능보험금', 'insurance_amount * deductible_payout_rate', '{"insurance_amount":"보험가입금액 number>=0","deductible_payout_rate":"자기부담비율별 지급비율(10%형 0.45 / 15%형 0.42 / 20%형 0.40 / 30%형 0.35 / 40%형 0.30) number 0..1"}', 'p.498', 'F-34', 2026);
INSERT OR IGNORE INTO formulas (id, name, equation_template, variables_schema, page_ref, node_id, version_year) VALUES ('F-35', '복분자 과실손해보험금', 'max(insurance_amount * (damage_rate - deductible_rate), 0)', '{"insurance_amount":"보험가입금액 number>=0","damage_rate":"피해율(고사결과모지수÷평년결과모지수) number 0..1","deductible_rate":"자기부담비율 number 0..1"}', 'p.498', 'F-35', 2026);
INSERT OR IGNORE INTO formulas (id, name, equation_template, variables_schema, page_ref, node_id, version_year) VALUES ('F-36', '복분자 피해율', 'dead_branches / expected_branches', '{"dead_branches":"고사결과모지수 number>=0","expected_branches":"평년결과모지수 number>0"}', 'p.498', 'F-36', 2026);
INSERT OR IGNORE INTO formulas (id, name, equation_template, variables_schema, page_ref, node_id, version_year) VALUES ('F-37', '복분자 5/31 이전 고사결과모지수', '(expected_branches - alive_branches) + invalid_pollination_dead - uncovered_dead', '{"expected_branches":"평년결과모지수 number>0","alive_branches":"살아있는 결과모지수 number>=0","invalid_pollination_dead":"수정불량환산 고사결과모지수 number>=0","uncovered_dead":"미보상 고사결과모지수 number>=0"}', 'p.498', 'F-37', 2026);
INSERT OR IGNORE INTO formulas (id, name, equation_template, variables_schema, page_ref, node_id, version_year) VALUES ('F-38', '복분자 6/1 이후 고사결과모지수', 'yield_loss_dead - uncovered_dead', '{"yield_loss_dead":"수확감소환산 고사결과모지수 number>=0","uncovered_dead":"미보상 고사결과모지수 number>=0"}', 'p.498', 'F-38', 2026);
INSERT OR IGNORE INTO formulas (id, name, equation_template, variables_schema, page_ref, node_id, version_year) VALUES ('F-39', '수정불량환산 고사결과모지수', 'alive_branches * invalid_pollination_factor', '{"alive_branches":"살아있는 결과모지수 number>=0","invalid_pollination_factor":"수정불량환산계수 number 0..1"}', 'p.498', 'F-39', 2026);
INSERT OR IGNORE INTO formulas (id, name, equation_template, variables_schema, page_ref, node_id, version_year) VALUES ('F-40', '수정불량환산계수', 'max((invalid_fruits / total_fruits) - natural_invalid_rate, 0)', '{"invalid_fruits":"수정불량결실수 number>=0","total_fruits":"전체결실수 number>0","natural_invalid_rate":"자연수정불량률(0.15, 2014 복분자 수확량 연구용역 결과) number 0..1"}', 'p.498', 'F-40', 2026);
INSERT OR IGNORE INTO formulas (id, name, equation_template, variables_schema, page_ref, node_id, version_year) VALUES ('F-41', '수확감소환산 고사결과모지수(5/31 이전 사고 있음)', '(alive_branches - invalid_pollination_dead) * cumulative_yield_loss_factor', '{"alive_branches":"살아있는 결과모지수 number>=0","invalid_pollination_dead":"수정불량환산 고사결과모지수 number>=0","cumulative_yield_loss_factor":"누적수확감소환산계수 number 0..1"}', 'p.499', 'F-41', 2026);
INSERT OR IGNORE INTO formulas (id, name, equation_template, variables_schema, page_ref, node_id, version_year) VALUES ('F-42', '수확감소환산 고사결과모지수(5/31 이전 사고 없음)', 'expected_branches * cumulative_yield_loss_factor', '{"expected_branches":"평년결과모지수 number>0","cumulative_yield_loss_factor":"누적수확감소환산계수 number 0..1"}', 'p.499', 'F-42', 2026);
INSERT OR IGNORE INTO formulas (id, name, equation_template, variables_schema, page_ref, node_id, version_year) VALUES ('F-43', '수확감소환산계수', 'residual_yield_ratio - fruit_setting_rate', '{"residual_yield_ratio":"수확일자별 잔여수확량 비율(별표 LAW-015 — 6/1~7=98-사고일자, 6/8~20=사고발생일자×사고발생일자) number 0..1","fruit_setting_rate":"결실률(전체결실수÷전체개화수) number 0..1"}', 'p.499', 'F-43', 2026);
INSERT OR IGNORE INTO formulas (id, name, equation_template, variables_schema, page_ref, node_id, version_year) VALUES ('F-44', '결실률', 'total_fruits / total_blossoms', '{"total_fruits":"전체결실수 number>=0","total_blossoms":"전체개화수 number>0"}', 'p.499', 'F-44', 2026);
INSERT OR IGNORE INTO formulas (id, name, equation_template, variables_schema, page_ref, node_id, version_year) VALUES ('F-45', '미보상 고사결과모지수', 'yield_loss_dead * max_uncovered_rate', '{"yield_loss_dead":"수확감소환산 고사결과모지수 number>=0","max_uncovered_rate":"MAX(특정위험 과실손해조사별 미보상비율) number 0..1"}', 'p.499', 'F-45', 2026);
INSERT OR IGNORE INTO formulas (id, name, equation_template, variables_schema, page_ref, node_id, version_year) VALUES ('F-46', '무화과 과실손해보험금', 'max(insurance_amount * (damage_rate - deductible_rate), 0)', '{"insurance_amount":"보험가입금액 number>=0","damage_rate":"피해율(7/31 이전 + 8/1 이후 합산) number 0..1","deductible_rate":"자기부담비율 number 0..1"}', 'p.499', 'F-46', 2026);
INSERT OR IGNORE INTO formulas (id, name, equation_template, variables_schema, page_ref, node_id, version_year) VALUES ('F-47', '무화과 7/31 이전 사고피해율', '(expected_yield - actual_yield - uncovered_loss) / expected_yield', '{"expected_yield":"평년수확량 number>0","actual_yield":"수확량 number>=0","uncovered_loss":"미보상감수량 number>=0"}', 'p.500', 'F-47', 2026);
INSERT OR IGNORE INTO formulas (id, name, equation_template, variables_schema, page_ref, node_id, version_year) VALUES ('F-48', '무화과 8/1 이후 사고피해율', '(1 - prior_damage_rate) * elapsed_ratio * branch_damage_rate', '{"prior_damage_rate":"수확전사고 피해율(7/31 이전 발생 기사고 피해율) number 0..1","elapsed_ratio":"경과비율(8월=100-1.06×사고일자, 9월=(100-33)-1.13×사고일자, 10월=(100-67)-0.84×사고일자, 단위 %) number 0..1","branch_damage_rate":"결과지피해율 number 0..1"}', 'p.500', 'F-48', 2026);
INSERT OR IGNORE INTO formulas (id, name, equation_template, variables_schema, page_ref, node_id, version_year) VALUES ('F-49', '무화과 결과지피해율', '(dead_branches + alive_branches * fruit_damage_rate - uncovered_dead_branches) / standard_branches', '{"dead_branches":"고사결과지수 number>=0","alive_branches":"미고사결과지수 number>=0","fruit_damage_rate":"착과피해율 number 0..1","uncovered_dead_branches":"미보상고사결과지수 number>=0","standard_branches":"기준결과지수(고사+미고사) number>0"}', 'p.500', 'F-49', 2026);
INSERT OR IGNORE INTO formulas (id, name, equation_template, variables_schema, page_ref, node_id, version_year) VALUES ('F-50', '무화과 기준결과지수', 'dead_branches + alive_branches', '{"dead_branches":"고사결과지수 number>=0","alive_branches":"미고사결과지수 number>=0"}', 'p.500', 'F-50', 2026);
INSERT OR IGNORE INTO formulas (id, name, equation_template, variables_schema, page_ref, node_id, version_year) VALUES ('F-51', '무화과 고사결과지수', 'covered_dead + uncovered_dead', '{"covered_dead":"보상고사결과지수 number>=0","uncovered_dead":"미보상고사결과지수 number>=0"}', 'p.500', 'F-51', 2026);
INSERT OR IGNORE INTO formulas (id, name, equation_template, variables_schema, page_ref, node_id, version_year) VALUES ('F-52', '무화과 나무손해보장 보험금', 'max(insurance_amount * (damage_rate - 0.05), 0)', '{"insurance_amount":"보험가입금액 number>=0","damage_rate":"피해율(피해주수÷실제결과주수) number 0..1"}', 'p.500', 'F-52', 2026);
INSERT OR IGNORE INTO formulas (id, name, equation_template, variables_schema, page_ref, node_id, version_year) VALUES ('F-53', '무화과 나무손해 피해율', 'dead_trees / actual_trees', '{"dead_trees":"피해주수(고사된 나무) number>=0","actual_trees":"실제결과주수 number>0"}', 'p.500', 'F-53', 2026);
INSERT OR IGNORE INTO formulas (id, name, equation_template, variables_schema, page_ref, node_id, version_year) VALUES ('F-54', '논작물 면적피해율(재이앙·재직파)', 'damaged_area / actual_area', '{"damaged_area":"피해면적(묘 분리/묻힘/잎차단/수확불가) number>=0","actual_area":"실제경작면적 number>0"}', 'p.505', 'F-54', 2026);
INSERT OR IGNORE INTO formulas (id, name, equation_template, variables_schema, page_ref, node_id, version_year) VALUES ('F-55', '논작물 식물체피해율(경작불능)', 'damaged_plant_ratio', '{"damaged_plant_ratio":"식물체 피해 비율(목측 조사) — 65% 이상(분질미 60% 이상) 시 경작불능보험금 분기 number 0..1"}', 'p.507', 'F-55', 2026);
INSERT OR IGNORE INTO formulas (id, name, equation_template, variables_schema, page_ref, node_id, version_year) VALUES ('F-56', '논작물 조사대상 면적', 'actual_area - dead_area - other_uncovered_area - already_harvested_area', '{"actual_area":"실제경작면적 number>0","dead_area":"고사면적(보장재해로 수확 불가) number>=0","other_uncovered_area":"타작물·미보상 면적 number>=0","already_harvested_area":"기수확면적(조사 전 수확 완료) number>=0"}', 'p.509', 'F-56', 2026);
INSERT OR IGNORE INTO formulas (id, name, equation_template, variables_schema, page_ref, node_id, version_year) VALUES ('F-57', '논작물 제현율(수확불능 트리거)', 'husk_removed_rate', '{"husk_removed_rate":"제현율(벼 껍질 벗긴 비율) — 65% 미만(분질미 70% 미만) 시 수확불능 트리거 number 0..1"}', 'p.509', 'F-57', 2026);
INSERT OR IGNORE INTO formulas (id, name, equation_template, variables_schema, page_ref, node_id, version_year) VALUES ('F-58', '수량요소조사 점수 합계', 'sum_panicle_scores + sum_full_grain_scores', '{"sum_panicle_scores":"이삭상태 점수 합(4 표본포기, 16미만=1, 16이상=2 — LAW-011) number 4..8","sum_full_grain_scores":"완전낟알상태 점수 합(4 표본포기, 5단계 1~5 — LAW-012) number 4..20"}', 'p.511', 'F-58', 2026);
INSERT OR IGNORE INTO formulas (id, name, equation_template, variables_schema, page_ref, node_id, version_year) VALUES ('F-59', '수량요소조사 수확비율', 'score_to_yield_ratio_lookup(score_sum)', '{"score_sum":"점수 합계 — LAW-013 환산표 lookup (10미만=0~20%, 10~11=21~40%, 12~13=41~50%, 14~15=51~60%, 16~18=61~70%, 19~21=71~80%, 22~23=81~90%, 24이상=91~100%) number 8..28"}', 'p.512', 'F-59', 2026);
INSERT OR IGNORE INTO formulas (id, name, equation_template, variables_schema, page_ref, node_id, version_year) VALUES ('F-60', '피해면적 보정계수', 'damage_correction_factor', '{"damage_correction_factor":"피해정도 보정 — 매우경미(<10%)=1.2, 경미(10~30%)=1.1, 보통(≥30%)=1.0 — LAW-014 number 1.0..1.2"}', 'p.512', 'F-60', 2026);

